import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int total_rounds = Integer.parseInt(scanner.nextLine().trim());
        int[] alice_moves = Arrays.stream(scanner.nextLine().split(" "))
                                  .mapToInt(Integer::parseInt)
                                  .toArray();
        int[] bob_moves = Arrays.stream(scanner.nextLine().split(" "))
                                .mapToInt(Integer::parseInt)
                                .toArray();

        int[] bob_moves_rotated = new int[bob_moves.length];
        for (int i = 0; i < bob_moves.length - 1; i++) {
            bob_moves_rotated[i] = bob_moves[i + 1];
        }
        bob_moves_rotated[bob_moves.length - 1] = bob_moves[0];

        int min_wins = 0;
        int max_wins = 0;

        for (int i = 0; i < total_rounds; i++) {
            min_wins += Math.min(alice_moves[i], bob_moves_rotated[i]);
        }

        int max_bob_choice = Arrays.stream(bob_moves_rotated).max().getAsInt();
        for (int i = 0; i < total_rounds; i++) {
            if (bob_moves_rotated[i] == max_bob_choice && bob_moves_rotated[i] + alice_moves[i] > min_wins) {
                min_wins = bob_moves_rotated[i] + alice_moves[i];
            }
        }

        int max_alice_choice = Arrays.stream(alice_moves).max().getAsInt();
        for (int i = 0; i < total_rounds; i++) {
            if (alice_moves[i] == max_alice_choice && alice_moves[i] + bob_moves_rotated[i] > min_wins) {
                min_wins = alice_moves[i] + bob_moves_rotated[i];
            }
        }

        if (min_wins > total_rounds) {
            min_wins -= total_rounds;
        } else {
            min_wins = 0;
        }

        System.out.println(min_wins + " " + max_wins);
        scanner.close();
    }
}
